 auto& paid=f.economy.payments.rows().back().second;auto amount=paid.amount;paid.amount+=1;check(!query_private_shop_daily_rent(read,"owner",query).ok,"wrong original amount is damaged source rather than displayed account");paid.amount=amount;check(compare_boundary(unchanged,encode_common_state(f.common.state())).exact(),"all history pagination remains resource read-only");
 f.common.state().metadata.player_actor_id="lessor";check(!query_private_shop_daily_rent(read,"lessor",query).ok,"same-place lessor gets no private account access");f.common.state().metadata.player_actor_id="owner";
 f.common_catalog->places.insert("far",{"far","town",{}});f.common.state().actors.find("owner")->location=SettlementLocation{"town","far"};auto remote=query_private_shop_daily_rent(read,"owner",query);check(remote.ok&&*remote.value.find("observation")->as<StableId>()=="firsthand_documents","remote owner retains original prepaid opening documents");check(!remote.value.find("outstanding")&&!remote.value.find("suspended")&&!remote.value.find("paid_cash")&&remote.value.find("actions")->as<Value::Array>()->empty(),"remote rent documents omit current debt suspension totals and previews");check(remote.value.find("history")->as<Value::Array>()->size()==2,"later automatic calendar payments are not silently delivered reports");f.common.state().actors.find("owner")->location=SettlementLocation{"town","market"};
