 auto due=read_private_shop_rent_ledger(f.common,f.economy,f.state,profile,rent,opened.value.shop_id);check(due.ok&&!due.value.pending_arrear_id.empty(),"original shop cash exhausted by actual paid periods");auto quote=preview_private_shop_daily_rent(read,"owner",PrivateShopPayRentArrear{opened.value.shop_id,due.value.assessment_fact_id,"owner.wallet",{}, {}});check(quote.ok,"real explicit proprietor payment quote");auto paid_source=apply_private_shop_daily_rent_in_candidate(f.common,f.economy,f.state,rent,read,quote.value);check(paid_source.ok,"original voluntary payment creates actual two-leg source");
